#include "connectors/snowflake/connector.hpp"
#include "config/connections/connection_config_reader.hpp"
#include <iostream>
#include <stdexcept>

namespace {
    void require(bool success, std::string_view message) {
        if (!success) throw std::runtime_error(std::string{message});
    }
    void require_ok(const core::error_t& error) {
        require(!error.contains_error(), error.what);
    }
}

// Runs only against the endpoint generated by test_snowflake_transport.py.
// The driver library path is configuration, and credentials are env references.
int main(int argc, char** argv) {
    try {
        require(argc == 3, "usage: snowflake_transport_probe CONFIG SCENARIO");
        const auto node = YAML::LoadFile(argv[1]);
        auto parsed = config::parse_connections(node["connections"], std::pmr::new_delete_resource());
        require(!parsed.has_error(), "invalid fixture configuration");
        require(parsed.value().snowflake.size() == 1, "fixture requires one connection");
        snowflake::Connector connector(std::pmr::new_delete_resource(), parsed.value().snowflake.front());
        const std::string scenario = argv[2];
        auto opened = connector.connect();
        if (scenario == "untrusted_ca" || scenario == "wrong_hostname") {
            require(opened.contains_error(), "invalid TLS peer was accepted");
        } else {
            require_ok(opened);
            if (scenario == "timeout" || scenario == "row_limit") {
                auto result = connector.execute("SELECT fixture_values");
                require(result.has_error(), "fixture must return a bounded failure");
            } else {
                auto result = connector.execute("SELECT fixture_values");
                require(!result.has_error(), result.has_error() ? result.error().what : "");
                require(result.value().columns.size() == 3 && result.value().rows.size() == 2, "incorrect result dimensions");
                require(result.value().columns[0].precision == 38 && result.value().columns[0].scale == 8, "decimal metadata changed");
                require(result.value().rows[0][0] == "123456789012345678901234567890.12345678", "decimal lost precision");
                require(result.value().rows[0][1] == std::string(20000, 'x'), "large text was truncated");
                const char binary[] = {'\0', '\0', static_cast<char>(0xff), 'A'};
                require(result.value().rows[0][2] == std::string(binary, sizeof(binary)), "binary value changed");
                require(!result.value().rows[1][0] && result.value().rows[1][1] == "" && !result.value().rows[1][2], "NULL and empty values changed");
                require_ok(connector.begin());
                auto write = connector.execute("INSERT INTO fixture_table VALUES (1)");
                require(!write.has_error(), write.has_error() ? write.error().what : "");
                require(write.value().affected_rows == 7, "affected row count changed");
                auto finished = connector.finish(scenario == "lost_commit" || scenario == "commit");
                if (scenario == "lost_commit") require(finished.contains_error(), "lost commit reply was acknowledged");
                else require_ok(finished);
                require(connector.execute("SELECT fixture_values").has_error(), "completed transaction socket was reused");
            }
        }
        std::cout << scenario << " PASS\n";
        return 0;
    } catch (const std::exception& error) {
        std::cerr << error.what() << '\n';
        return 1;
    }
}
